mapper.select:
select cusip from Sec_Price where price_date=#{asOfDate} 

	and cusip in

	#{item}

select secprice0_.id as priceid, secprice0_.sourceID as sourceid, interfaces2_.sourceDesc as sourcename, issueinfo3_.SECURITYID as secid, issueinfo3_.securityname as secname, fxcurrency1_.CURR_CODE as curency, secprice0_.PRICE as price, secprice0_.PRICE_DATE as priceDate, secprice0_.priceto as priceto, secprice0_.yield as yield from SEC_PRICE secprice0_, InterfaceSource interfaces2_, ISSUE_INFO issueinfo3_ cross join FX_CURRENCY fxcurrency1_ where secprice0_.sourceID=interfaces2_.sourceID and secprice0_.CUSIP=issueinfo3_.CUSIP and issueinfo3_.PriCur=fxcurrency1_.CURR_ID
and secprice0_.sourceID in
#{item}
and secprice0_.securityid={secid}
and secprice0_.PRICE_DATE>=#{startDate}
and secprice0_.PRICE_DATE<=#{endDate}
order by secprice0_.PRICE_DATE desc,id desc
